def format_bytes(n):
    "Return a human‑readable size string for a given number of bytes"  # noqa
    units = ['B', 'KB', 'MB', 'GB', 'TB']
    if n < 1024:
        return f'{n:.1f} {units[0]}'
    for unit in units[1:]:
        if n < 1024 ** (len(units) - 1):
            return f'{n / 1024:.1f} {unit}'
    return f'{n / 1024**4:.1f} {units[-1]}'
